import urllib.request, json
sid='8600d2c88d964764b2fbc86c1c108486'; url='http://are-sidecar:8000/mcp'
headers={'Content-Type':'application/json','Accept':'application/json, text/event-stream','mcp-session-id':sid}
_id=500
def call(name,args=None):
    global _id
    if args is None: args={}
    payload={"jsonrpc":"2.0","id":_id,"method":"tools/call","params":{"name":name,"arguments":args}}
    _id+=1
    req=urllib.request.Request(url, data=json.dumps(payload).encode(), headers=headers, method='POST')
    raw=urllib.request.urlopen(req).read().decode()
    text='\n'.join(line[6:] for line in raw.splitlines() if line.startswith('data: '))
    data=json.loads(text)
    cont=data['result']['content'][0]['text']
    try: cont=json.loads(cont)
    except Exception: pass
    return cont
for q in ['Åke','Ake','Svensson','producer','film','Stockholm','Sweden']:
    print('\nSEARCH', q)
    print(json.dumps(call('Contacts__search_contacts', {'query':q}), indent=2, ensure_ascii=False))
print('\nLOCAL FILTER')
for off in range(0,130,10):
    res=call('Contacts__get_contacts', {'offset':off})['result']
    for c in res.get('contacts',[]):
        blob=json.dumps(c, ensure_ascii=False).lower()
        if any(t in blob for t in ['stockholm','sweden','swedish','film','producer']):
            print(c.get('contact_id'), c.get('first_name'), c.get('last_name'), '|', c.get('city_living'), c.get('country'), '|', c.get('job'), '|', c.get('email'))
